def compute(vars):
    increase = vars["v1"]
    decrease = vars["v2"]
    net_change = increase + decrease

    return {
        "value": net_change,
        "trace": {
            "increase": increase,
            "decrease": decrease,
            "net_change": net_change,
            "output_meta": {
                "currency": "USD",
                "scale": None,
                "unit": None
            }
        }
    }
